import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
/* eslint-disable */
import { get_global_categories } from "@/mixins/GetGlobalCategories.js";
import { get_material_unit } from "@/mixins/GetMaterialUnit.js";
import { quotation_sub_categories } from "@/graphql/mutations.js";
import { get_all_org_suppliers } from "@/mixins/GetSuppliers.js";
import { API, graphqlOperation } from "aws-amplify";
import { uploadToS3 } from "@/mixins/S3PutStorageFile.js";
import CurrencyList from "@/JsonFiles/CurrencyList.json";
var AWS = require("aws-sdk");
import { Buffer } from "buffer";
export default {
  mixins: [get_global_categories, get_material_unit, get_all_org_suppliers],
  props: {
    ItemsAddition: Boolean
  },
  data() {
    return {
      itemType: "PRODUCT",
      productName: "",
      supplierItemsku: "",
      categorys: "",
      supplierItembrand: "",
      supplierItemdescription: "",
      unitstype: [],
      supplierItemmrp: "",
      supplierItemsellingPrice: "",
      currency: "",
      currencyItems: [],
      supplierItemtaxRate: "",
      supplierItemproductName: "",
      servicecost: "",
      loading: false,
      rules: {
        required: value => !!value || "This field is required"
      }
    };
  },
  watch: {
    ItemsAddition: {
      async handler() {
        if (this.ItemsAddition == true) {
          this.itemType = "PRODUCT";
          this.currency = "";
          await this.get_global_categories();
          await this.get_material_unit();
          // await this.get_all_org_suppliers();
        }
      },
      immediate: true
    }
  },
  created() {
    this.currencyItems = CurrencyList.map(item => ({
      title: `${item.currency_code} - ${item.country}`,
      value: item.currency_code
    }));
  },
  methods: {
    onlyNumbers(event) {
      if (!/[0-9]/.test(event.key)) {
        event.preventDefault();
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        await this.add_mutation();
      } else {
        // await this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(quotation_sub_categories, {
          input: {
            category_id: !this.categorys ? undefined : this.categorys,
            sub_category_name: !this.productName ? undefined : this.productName,
            sub_category_Sku: !this.supplierItemsku ? undefined : this.supplierItemsku,
            sub_category_description: !this.supplierItemdescription ? undefined : this.supplierItemdescription,
            sub_category_unit: this.unitstype.length == 0 ? undefined : this.unitstype,
            currency: !this.currency ? undefined : this.currency,
            sub_category_retail_price: !this.supplierItemmrp ? undefined : this.supplierItemmrp,
            sub_category_selling_price: !this.supplierItemsellingPrice ? undefined : this.supplierItemsellingPrice,
            sub_category_tax: !this.supplierItemtaxRate ? undefined : this.supplierItemtaxRate,
            action_type: "CREATE",
            sub_category_type: this.itemType,
            brand_name: !this.supplierItembrand ? undefined : this.supplierItembrand
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.quotation_sub_categories);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "update");
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
          // console.log(response.Message);
        }
      } catch (error) {
        // console.log(error)
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
